insert into public.pvp_pow_identity_v1881(pow_id,primary_role,secondary_role,archetype,passive_name,passive_summary,synergy,signature,source_version) values
('pyroon','Xạ thủ','Kết liễu','Hỏa Thiêu Đốt','Tập Trung','Tập Trung: đánh liên tiếp cùng một mục tiêu nhận 1 tầng, tối đa 3. Đổi mục tiêu mất toàn bộ tầng.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','e1e93687','18.8.1'),
('voltkit','Pháp sư','Khống chế','Sét Crit / Điện Tích / Tempo','Tĩnh Điện','Tĩnh Điện: kỹ năng đặt tầng lên kẻ địch, tối đa 3 mỗi mục tiêu. Tiêu tầng để tạo sát thương lan và Quá Tải nhẹ; bậc Thường không có khống chế cứng.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','bb4f0d42','18.8.1'),
('terrapup','Đỡ đòn','Kết liễu','Đất Thành Lũy / Phản Chấn','Đất Nén','Đất Nén: nhận sát thương trực tiếp tạo 1 tầng, tối đa 4. Dùng để dựng khiên và phản chấn; không tăng sát thương chủ lực.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','84b14bae','18.8.1'),
('aquabub','Đấu sĩ','Bảo hộ','Nước Sustain / Mana / Triều','Hai Thủy Thế luân phiên','Hai Thủy Thế luân phiên: Lưu Thủy thiên hồi phục/nhịp lượt, Phá Lãng thiên sát thương/đẩy lượt. Mỗi hành động đổi sang thế còn lại.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','10223d42','18.8.1'),
('gearbit','Hiệp sĩ','Bảo hộ','Thép Khiên / Lời Thề','Đồng Minh Lời Thề được chọn đầu trận','Đồng Minh Lời Thề được chọn đầu trận. Mỗi lần bảo vệ thành công nhận 1 Bánh Răng, tối đa 3; đủ 3 làm đòn cơ bản kế tiếp xoay kép.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','824c82e3','18.8.1'),
('zephyroo','Thuật sư','Khống chế','Gió SPEED / Turn Tempo','Điều khiển thanh lượt bằng Luồng Gió, không hồi HP','Điều khiển thanh lượt bằng Luồng Gió, không hồi HP. Kỹ năng luôn có cái giá là tự chậm, giới hạn mục tiêu lặp hoặc chỉ chuyển chứ không tạo vô hạn lượt.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','1aea2646','18.8.1'),
('mosshorn','Trị liệu','Bảo hộ','Lá Hồi Phục / Sinh Trưởng','Hạt Mầm được gieo lên đồng minh thấp HP','Hạt Mầm được gieo lên đồng minh thấp HP. Kỹ năng hồi máu làm Mầm nảy nở thành Hồi phục theo lượt hoặc Khiên; không có Thanh tẩy hoàn chỉnh.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','84015f8b','18.8.1'),
('cindlet','Xạ thủ','Kết liễu','Hỏa Thiêu Đốt','Hỏa Đạn','Hỏa Đạn: đòn cơ bản nạp 1 viên, tối đa 3. Kỹ năng dùng số đạn để tăng số phát bắn; cơ chế trực tiếp, dễ hiểu.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','33d1f186','18.8.1'),
('joltail','Xạ thủ','Kết liễu','Sét Crit / Điện Tích / Tempo','Bộ Đếm Ba Phát','Bộ Đếm Ba Phát: mỗi đòn cơ bản tăng bộ đếm; phát thứ ba tự bắn thêm một tia phụ. Không cần tích tài nguyên phức tạp.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','e18d23d1','18.8.1'),
('emberix','Pháp sư','Bào mòn','Hỏa Thiêu Đốt','Hỏa Ấn','Hỏa Ấn: kỹ năng đặt Ấn lên mục tiêu, đủ 3 Ấn phát nổ. Vòng lặp đơn giản: đặt – gom – kích nổ.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','3b4b9603','18.8.1'),
('mudram','Đỡ đòn','Bảo hộ','Đất Thành Lũy / Phản Chấn','Kho Bùn','Kho Bùn: lưu một phần sát thương trực tiếp đã nhận, sau đó chuyển thành Khiên hoặc sát thương DEF. Không tăng DPS ngoài tài nguyên đã chịu đòn.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','7fdfe322','18.8.1'),
('rivetoad','Đỡ đòn','Bảo hộ','Thép Khiên / Lời Thề','Khiên Đinh Tán','Khiên Đinh Tán: mọi kỹ năng đều dựng Khiên; lần đầu Khiên bị phá trong vòng sẽ bắn đinh phản công.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','ff6181de','18.8.1'),
('dusthorn','Sát thủ','Kết liễu','Đất Thành Lũy / Phản Chấn','Đà Lao','Đà Lao: mỗi hành động gây hoặc nhận sát thương trực tiếp cho 1 Đà, tối đa 3. Skill 1 tiêu Đà để tăng sát thương.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','539c8eba','18.8.1'),
('sparkit','Đấu sĩ','Bảo hộ','Sét Crit / Điện Tích / Tempo','Liên Hoàn','Liên Hoàn: luân phiên đòn cơ bản và kỹ năng để tăng chuỗi, tối đa 3. Dùng lặp cùng loại hành động làm chuỗi về 0.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','4c53a70d','18.8.1'),
('streami','Hiệp sĩ','Bảo hộ','Nước Sustain / Mana / Triều','Song Thế Công–Thủ','Song Thế Công–Thủ: Skill 1 luân phiên hai thế. Công Thế gây áp lực; Thủ Thế tạo Khiên cho Đồng Minh Lời Thề.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','4668642c','18.8.1'),
('tinwing','Sát thủ','Kết liễu','Thép Khiên / Lời Thề','Hộ Tống Tốc Độ','Hộ Tống Tốc Độ: bảo vệ Đồng Minh Lời Thề bằng giảm sát thương và đẩy nhịp hành động, không nhận đòn thay toàn phần như Đỡ đòn.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','a0e57668','18.8.1'),
('budtail','Thuật sư','Khống chế','Lá Hồi Phục / Sinh Trưởng','Chồi Theo Role','Chồi Theo Role: buff đơn giản thay đổi theo role mục tiêu; không hồi HP và không Thanh tẩy.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','b958b209','18.8.1'),
('windlet','Thuật sư','Khống chế','Gió SPEED / Turn Tempo','Chuyển Nhịp','Chuyển Nhịp: lấy một phần thanh lượt từ kẻ địch rồi chuyển cho đồng minh; tổng lượng chuyển luôn hữu hạn.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','8ad60404','18.8.1'),
('brookfin','Trị liệu','Duy trì','Nước Sustain / Mana / Triều','Hồi Phục Nảy','Hồi Phục Nảy: hồi mục tiêu chính rồi nảy sang đồng minh thấp HP tiếp theo; hiệu quả nảy thấp hơn, không Thanh tẩy.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','4f9daca4','18.8.1'),
('spriggle','Trị liệu','Duy trì','Lá Hồi Phục / Sinh Trưởng','Hạt Chồi','Hạt Chồi: gieo Hạt lên đồng minh; lần hồi tiếp theo làm Hạt nở thành Hồi phục theo lượt. Cơ chế chuẩn bị đơn giản, không Thanh tẩy.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','c92a8941','18.8.1')
insert into public.pvp_pow_identity_v1881(pow_id,primary_role,secondary_role,archetype,passive_name,passive_summary,synergy,signature,source_version) values
('whisprill','Nhạc công','Điều lượt','Gió SPEED / Turn Tempo','Khúc Gió Mở Màn','Khúc Gió Mở Màn: tự phát trước lượt đầu; sau mỗi 3 hành động đồng minh nhận 1 Phách, đủ 3 Phách mở Điệp Khúc. Cơ chế ở mức nhập môn.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','b6f16fde','18.8.1'),
('torrento','Xạ thủ','Kết liễu','Nước Sustain / Mana / Triều','Phối Hợp Hỏa Lực','Phối Hợp Hỏa Lực: khi đồng minh đánh mục tiêu Torrento đang khóa, nhận 1 Phối Hợp, tối đa 2. Tiêu để thêm phát hỗ trợ.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','0c3a662e','18.8.1'),
('voltraptor','Xạ thủ','Kết liễu','Sét Crit / Điện Tích / Tempo','Dấu Săn Điện','Dấu Săn Điện: chí mạng hoặc Skill 2 đặt Dấu; kỹ năng đặc trưng khai thác Dấu để thêm một phát điện.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','ddfe3bf3','18.8.1'),
('arclynx','Pháp sư','Điều lượt','Sét Crit / Điện Tích / Tempo','Nút Hồ Quang','Nút Hồ Quang: rải Nút lên nhiều mục tiêu rồi nối chúng bằng tia điện. Mỗi mục tiêu tối đa 2 Nút.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','7b10009a','18.8.1'),
('cindercore','Pháp sư','Bảo hộ','Dung Nham Phá Khiên / Nứt Giáp','Nhiệt Lõi','Nhiệt Lõi: kỹ năng tiêu Mana tạo 1 Nhiệt, tối đa 3. Nhiệt tăng sát thương nhưng chỉ Ultimate tiêu toàn bộ.','Carry phá Khiên, đội gây áp lực tuyến trước, debuff DEF.','fd1bb9c0','18.8.1'),
('embermole','Sát thủ','Kết liễu','Hỏa Thiêu Đốt','Than Ngầm','Than Ngầm: đặt một mồi nổ trì hoãn lên mục tiêu, sau đó kích nổ bằng kỹ năng khác. Mỗi mục tiêu tối đa một mồi.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','2ee9d13f','18.8.1'),
('bouldrax','Đỡ đòn','Kết liễu','Đất Thành Lũy / Phản Chấn','Phiến Đá','Phiến Đá: bắt đầu với 3 Phiến; mỗi Phiến giảm sát thương trực tiếp, bị mất khi nhận đòn. Kỹ năng tái tạo Phiến.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','282d774c','18.8.1'),
('quakeback','Đỡ đòn','Bảo hộ','Đất Thành Lũy / Phản Chấn','Dư Chấn','Dư Chấn: đòn trực tiếp đầu tiên nhận trong mỗi vòng lưu 25% sát thương làm Dư Chấn. Có thể chuyển thành Khiên hoặc phản trả theo DEF.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','164a1090','18.8.1'),
('ashmane','Đấu sĩ','Duy trì','Hỏa Thiêu Đốt','Cuồng Tro','Cuồng Tro: mỗi khi mất đủ 10% HP tối đa do sát thương, nhận 1 Cuồng Tro, tối đa 4. Dùng để tăng sát thương và tự duy trì.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','37a2647a','18.8.1'),
('vinerex','Đấu sĩ','Bảo hộ','Lá Hồi Phục / Sinh Trưởng','Dây Bám','Dây Bám: đánh cùng mục tiêu tạo 1 Dây Bám, tối đa 3; đổi mục tiêu mất tầng. Đủ tầng mở một nhát bổ sung.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','c362632a','18.8.1'),
('ferrolyn','Hiệp sĩ','Bảo hộ','Thép Khiên / Lời Thề','Từ Ấn Hộ Vệ','Từ Ấn Hộ Vệ: đặt dấu lên kẻ địch; nếu kẻ đó đánh Đồng Minh Lời Thề, Ferrolyn phản kích một lần.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','1eb27a5a','18.8.1'),
('steelpaw','Hiệp sĩ','Bảo hộ','Thép Khiên / Lời Thề','Song Khiên','Song Khiên: Steelpaw và Đồng Minh Lời Thề cùng nhận Khiên; kỹ năng cân bằng và chuyển hóa tổng Khiên thành áp lực.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','c6b07f63','18.8.1'),
('thornclaw','Sát thủ','Kết liễu','Lá Hồi Phục / Sinh Trưởng','Bẫy Kỹ Năng','Bẫy Kỹ Năng: đặt bẫy lên một kẻ địch; bẫy chỉ kích hoạt khi mục tiêu dùng kỹ năng có Mana, không kích hoạt từ đòn cơ bản.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','8402874f','18.8.1'),
('toxiclaw','Sát thủ','Kết liễu','Độc DoT / Anti-heal','Độc Tích Lũy','Độc Tích Lũy: gây sát thương nhỏ theo lượt và giảm hiệu quả hồi phục ở mức nhẹ; không có Nguyền rủa.','Đội DoT, anti-heal, đánh dài, execute mục tiêu bị bào mòn.','9b57a243','18.8.1'),
('frostfeather','Trị liệu','Kết liễu','Băng Chill / Freeze','Hồi Dư Thành Khiên Băng','Hồi Dư Thành Khiên Băng: phần hồi vượt HP chuyển một phần thành Khiên; không Đóng Băng và không Thanh tẩy.','Pow Nước/Chill, control, carry đánh mục tiêu bị chậm/Frozen.','e03748ae','18.8.1'),
('hydripple','Trị liệu','Duy trì','Nước Sustain / Mana / Triều','Sóng Hồi Mana','Sóng Hồi Mana: hồi HP kèm Mana nhỏ, giúp đội xoay kỹ năng nhưng không tạo tài nguyên vô hạn.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','a6dc2fd1','18.8.1'),
('aeralune','Nhạc công','Duy trì','Gió SPEED / Turn Tempo','Khúc Trăng Hồi Mana','Khúc Trăng Hồi Mana: mở combat bằng Mana; sau mỗi 3 hành động đồng minh nhận 1 Phách, đủ 3 Phách mở Điệp Khúc.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','c112ff80','18.8.1'),
('skydart','Sát thủ','Kết liễu','Gió SPEED / Turn Tempo','Khúc Chí Mạng','Khúc Chí Mạng: mở combat cho chủ lực vật lý; chí mạng của đồng minh tạo Phách nhưng mỗi hành động chỉ được một Phách.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','348d18e4','18.8.1'),
('stormdash','Nhạc công','Điều lượt','Bão Điều Lượt / Nhịp','Trống Bão Lệch Nhịp','Trống Bão Lệch Nhịp: mở combat làm chậm nhẹ hai kẻ địch nhanh nhất; Phách được tạo từ hành động đồng minh như Nhạc công chuẩn.','Đội turn-control, nhiều hành động/Mana, carry hưởng lợi từ kéo nhịp.','e329c5ca','18.8.1'),
('ironmantis','Xạ thủ','Kết liễu','Thép Khiên / Lời Thề','Từ Nhận','Từ Nhận: mỗi lần đánh cùng mục tiêu tạo 1 Từ Nhận, tối đa 3; đổi mục tiêu chỉ mất 1 tầng thay vì mất hết.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','e38d47f0','18.8.1')
insert into public.pvp_pow_identity_v1881(pow_id,primary_role,secondary_role,archetype,passive_name,passive_summary,synergy,signature,source_version) values
('pyrewing','Xạ thủ','Kết liễu','Hỏa Thiêu Đốt','Độ Cao','Độ Cao: dùng kỹ năng nhận 1 Độ Cao, tối đa 2; bị đánh trực tiếp mất 1. Độ Cao tăng sát thương và mở cú bổ nhào.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','e83e3cb6','18.8.1'),
('thunderhorn','Xạ thủ','Kết liễu','Sét Crit / Điện Tích / Tempo','Lôi Sừng','Lôi Sừng: mỗi đòn chí mạng hoặc kỹ năng đồng minh tiêu Mana tạo 1 Điện Tích, tối đa 4; mỗi hành động chỉ nhận 1.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','2ae49c0c','18.8.1'),
('arcbison','Pháp sư','Khống chế','Sét Crit / Điện Tích / Tempo','Cột Dẫn','Cột Dẫn: mục tiêu bị Chậm, Tê Liệt, Trói hoặc Choáng nhận Cột Dẫn; kỹ năng sét nảy mạnh hơn qua các Cột Dẫn.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','9b178508','18.8.1'),
('gloompelt','Sát thủ','Kết liễu','Bóng Tối Curse / Execute','Ảnh Thực','Ảnh Thực: gây sát thương phép để tích Bóng Mờ; hút Mana và đặt Nguyền rủa — cơ chế độc quyền hệ Bóng tối.','Đội Curse, execute, hút Mana, dồn mục tiêu thấp HP.','97d41c79','18.8.1'),
('lavarax','Pháp sư','Kết liễu','Dung Nham Phá Khiên / Nứt Giáp','Nham Áp Phun Trào','Nham Áp: kỹ năng tạo Áp Suất, tối đa 4; ở 4 Áp Suất kỹ năng kế tiếp Phun Trào và xóa toàn bộ.','Carry phá Khiên, đội gây áp lực tuyến trước, debuff DEF.','c5bbcfe8','18.8.1'),
('pebblit','Đỡ đòn','Kết liễu','Đất Thành Lũy / Phản Chấn','Phiến Đá Xếp','Phiến Đá Xếp: bắt đầu với 3 Phiến; mỗi Phiến giảm 8% sát thương trực tiếp. Phiến vỡ khi nhận đòn vượt 12% HP tối đa.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','a9736878','18.8.1'),
('tidewarden','Đỡ đòn','Kết liễu','Nước Sustain / Mana / Triều','Mực Triều','Mực Triều: nhận 1 Mực Triều khi đồng minh được Khiên hoặc hồi HP, tối đa 4; dùng để tăng bảo hộ và hồi Mana nhẹ.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','b5d4411f','18.8.1'),
('verdantusk','Đỡ đòn','Kết liễu','Lá Hồi Phục / Sinh Trưởng','Vòng Sinh Trưởng','Vòng Sinh Trưởng: nhận hồi máu tạo 1 Sinh Trưởng, tối đa 4; mỗi tầng tăng DEF nhưng giảm dần hiệu quả.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','05421603','18.8.1'),
('magmafang','Đấu sĩ','Kết liễu','Dung Nham Phá Khiên / Nứt Giáp','Nham Nộ','Nham Nộ: gây hoặc nhận sát thương tạo Nham Nộ, tối đa 5; mỗi hành động tối đa 1. Tiêu để gây AOE và hút máu.','Carry phá Khiên, đội gây áp lực tuyến trước, debuff DEF.','a0d9c9e3','18.8.1'),
('mirefang','Sát thủ','Kết liễu','Độc DoT / Anti-heal','Săn Mùi Độc','Săn Mùi Độc: mục tiêu càng nhiều Độc, Mirefang càng tăng hút máu và sát thương kết liễu; không dùng Nguyền rủa.','Đội DoT, anti-heal, đánh dài, execute mục tiêu bị bào mòn.','84f4360b','18.8.1'),
('scorchmane','Đấu sĩ','Duy trì','Hỏa Thiêu Đốt','Nhiệt Chiến','Nhiệt Chiến: mất 10% HP tối đa cộng dồn nhận 1 Nhiệt, tối đa 5; Nhiệt tăng ATK nhưng không tăng DEF.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','48188727','18.8.1'),
('aegiscarab','Hiệp sĩ','Bảo hộ','Thép Khiên / Lời Thề','Giáp Phản Quang','Giáp Phản Quang: chọn Đồng Minh Lời Thề; Khiên trên hai mục tiêu tích Quang Giáp, tối đa 3, để phản đòn.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','a3373e78','18.8.1'),
('rimehorn','Hiệp sĩ','Khống chế','Băng Chill / Freeze','Tường Sương','Tường Sương: tạo Khiên Băng cho Đồng Minh Lời Thề; Khiên vỡ tạo Sương Giá và tích Mảnh Băng.','Pow Nước/Chill, control, carry đánh mục tiêu bị chậm/Frozen.','65b8bf19','18.8.1'),
('tidefang','Hiệp sĩ','Bảo hộ','Nước Sustain / Mana / Triều','Hộ Triều','Hộ Triều: Lời Thề nhận Dấu Triều; hồi máu/Khiên trên mục tiêu tích Thủy Ấn để tạo sóng phản công.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','56b21112','18.8.1'),
('frostwing','Thuật sư','Khống chế','Băng Chill / Freeze','Sương Nhịp','Sương Nhịp: giảm SPEED/thanh lượt để tích Sương trên mục tiêu; đủ 3 Sương mở Đóng Băng có giới hạn.','Pow Nước/Chill, control, carry đánh mục tiêu bị chậm/Frozen.','7c4acd72','18.8.1'),
('geoquill','Thuật sư','Khống chế','Đất Thành Lũy / Phản Chấn','Khe Nứt','Khe Nứt: đặt bẫy lên mục tiêu/ô hành động; khi kẻ địch dùng kỹ năng, Khe Nứt tăng cấp rồi sụp.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','ad605029','18.8.1'),
('bloomlord','Trị liệu','Kết liễu','Lá Hồi Phục / Sinh Trưởng','Nụ Sinh Mệnh','Nụ Sinh Mệnh: hồi mục tiêu dưới 50% HP tạo Nụ; Nụ nở sau hành động tiếp theo để hồi thêm và tăng AP/ATK phù hợp.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','f2657754','18.8.1'),
('lumibloom','Trị liệu','Kết liễu','Ánh Sáng Cleanse / Bảo Hộ','Quang Phấn','Quang Phấn: hồi máu tạo Hạt Sáng; dùng Hạt để Thanh tẩy có chọn lọc — quyền riêng của hệ Ánh sáng.','Đội cần Cleanse, bảo hộ và chống debuff; phù hợp carry dễ bị khóa.','e2bd7ab8','18.8.1'),
('cloudtalon','Nhạc công','Điều lượt','Gió SPEED / Turn Tempo','Không Nhịp','Không Nhịp: mở combat bằng khúc tăng tốc; chí mạng đồng minh tạo Phách Bay, đủ 4 phát động Điệp Khúc.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','fdb0bf07','18.8.1'),
('galehart','Nhạc công','Khống chế','Gió SPEED / Turn Tempo','Kèn Gió Ba Nhịp','Kèn Gió Ba Nhịp: mỗi 3 hành động đồng minh tạo một Nhịp Kèn; Nhịp 1 tăng tốc, Nhịp 2 tăng phòng thủ, Nhịp 3 tăng tấn công rồi lặp.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','2be052f4','18.8.1')
insert into public.pvp_pow_identity_v1881(pow_id,primary_role,secondary_role,archetype,passive_name,passive_summary,synergy,signature,source_version) values
('tempestfin','Nhạc công','Duy trì','Bão Điều Lượt / Nhịp','Trống Sấm','Trống Sấm: kỹ năng đồng minh tiêu Mana tạo Phách Sấm, kỹ năng điều khiển lượt tạo Phách Gió; đủ cặp kích hoạt Điệp Khúc Bão.','Đội turn-control, nhiều hành động/Mana, carry hưởng lợi từ kéo nhịp.','54d0f61f','18.8.1'),
('voltfang','Xạ thủ','Kết liễu','Sét Crit / Điện Tích / Tempo','Mạch Lôi','Mạch Lôi: lần đầu mỗi vòng khi một đồng minh dùng kỹ năng tiêu Mana, nhận 1 Mạch; khi đánh mục tiêu có Khiên nhận thêm 1; tối đa 8.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','3aacc791','18.8.1'),
('ignivar','Pháp sư','Bào mòn','Hỏa Thiêu Đốt','Hỏa Lệnh','Hỏa Lệnh: lần đầu mỗi vòng khi một Pow Lửa dùng kỹ năng hoặc một kẻ địch nhận Thiêu đốt, nhận 1 Hỏa Lệnh; tối đa 6.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','c215d7f3','18.8.1'),
('volcarnos','Pháp sư','Bảo hộ','Dung Nham Phá Khiên / Nứt Giáp','Nham Áp Phá Thành','Nham Áp: gây sát thương lên Khiên hoặc nhận sát thương trực tiếp tạo 1 Nham Áp; tối đa 6, mỗi hành động tối đa 1.','Carry phá Khiên, đội gây áp lực tuyến trước, debuff DEF.','b608b729','18.8.1'),
('stoneback','Đỡ đòn','Kết liễu','Đất Thành Lũy / Phản Chấn','Kiến Thành','Kiến Thành: nhận hoặc chặn đòn trực tiếp tạo 1 tầng; AOE chỉ tạo 1 tầng mỗi vòng; tối đa 6.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','6054f1e8','18.8.1'),
('tidecrest','Đỡ đòn','Bảo hộ','Nước Sustain / Mana / Triều','Thủy Thế','Thủy Thế: mỗi lần HP bản thân thay đổi ít nhất 8% hoặc bảo hộ thành công nhận 1 tầng; tối đa 6, mỗi hành động tối đa 1.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','705b3d9d','18.8.1'),
('blazetalon','Đấu sĩ','Bảo hộ','Hỏa Thiêu Đốt','Chiến Hỏa','Chiến Hỏa: mỗi lượt hành động chính gây sát thương khi còn trên 40% HP nhận 1 tầng; đỡ đòn thành công nhận thêm 1; tối đa 6.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','203e62de','18.8.1'),
('venomtail','Đấu sĩ','Duy trì','Độc DoT / Anti-heal','Độc Huyết','Độc Huyết: mỗi lần Độc của bất kỳ bên nào gây sát thương nhận 1 tầng, tối đa 8; mỗi vòng tối đa 2.','Đội DoT, anti-heal, đánh dài, execute mục tiêu bị bào mòn.','7195c4c7','18.8.1'),
('frostpelt','Hiệp sĩ','Khống chế','Băng Chill / Freeze','Băng Thệ','Băng Thệ: bảo hộ thành công hoặc đánh mục tiêu bị Chậm/Hàn Khí tạo 1 tầng; tối đa 6.','Pow Nước/Chill, control, carry đánh mục tiêu bị chậm/Frozen.','bfb75c48','18.8.1'),
('ironmane','Hiệp sĩ','Bảo hộ','Thép Khiên / Lời Thề','Long Giáp','Long Giáp: chặn, phản kích hoặc kháng thành công một debuff tạo 1 tầng; tối đa 6, mỗi hành động tối đa 1.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','566edd61','18.8.1'),
('bramblet','Thuật sư','Khống chế','Lá Hồi Phục / Sinh Trưởng','Sinh Trưởng','Sinh Trưởng: lần đầu mỗi vòng khi buff đồng minh hoặc debuff kẻ địch nhận 1 Mầm Chiến; nếu cả hai xảy ra trong cùng vòng nhận thêm 1; tối đa 6.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','34ee2188','18.8.1'),
('coralyn','Thuật sư','Khống chế','Nước Sustain / Mana / Triều','Triều Ấn','Triều Ấn: lần đầu mỗi vòng khi đồng minh nhận hoặc tiêu ít nhất 20 Mana tạo 1 Ấn; tối đa 6.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','1710b28b','18.8.1'),
('sunfeather','Trị liệu','Bảo hộ','Ánh Sáng Cleanse / Bảo Hộ','Quang Vũ','Quang Vũ: hồi máu trực tiếp, Thanh tẩy hoặc xóa buff thành công tạo 1 tầng; tối đa 6, mỗi kỹ năng tối đa 1.','Đội cần Cleanse, bảo hộ và chống debuff; phù hợp carry dễ bị khóa.','5b43095d','18.8.1'),
('thorncrest','Trị liệu','Bảo hộ','Lá Hồi Phục / Sinh Trưởng','Niên Luân','Niên Luân: đầu mỗi vòng từ vòng 2 nhận 1; hồi dư từ kỹ năng tạo thêm 1, tối đa 6; mỗi vòng tối đa 2.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','ecc35613','18.8.1'),
('galehowl','Nhạc công','Điều lượt','Gió SPEED / Turn Tempo','Nhịp Gió','Nhịp Gió: sau mỗi 2 hành động chính của đồng minh nhận 1 Nhịp; tối đa 8; hành động chen không tính.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','e1e655fd','18.8.1'),
('stormcoil','Nhạc công','Bảo hộ','Bão Điều Lượt / Nhịp','Điện Nhịp','Điện Nhịp: đồng minh tiêu Mana hoặc bất kỳ thanh lượt nào thay đổi ít nhất 10% tạo 1 tầng; tối đa 8, mỗi hành động tối đa 1.','Đội turn-control, nhiều hành động/Mana, carry hưởng lợi từ kéo nhịp.','19718383','18.8.1'),
('nightclaw','Sát thủ','Kết liễu','Bóng Tối Curse / Execute','Dạ Liệp','Dạ Liệp: cuối lượt hành động chính, nếu từ lượt trước chưa bị đòn đơn mục tiêu đánh trúng, nhận 1 Ẩn Tức; tối đa 5. Phản kích/truy kích không tạo Ẩn Tức.','Đội Curse, execute, hút Mana, dồn mục tiêu thấp HP.','8106da1c','18.8.1'),
('thunderos','Xạ thủ','Kết liễu','Sét Crit / Điện Tích / Tempo','Luật Lôi Đình','Luật Lôi Đình: lần chí mạng đầu tiên mỗi vòng của Thunderos tạo 2 Điện Tích thay vì 1. Khi đánh mục tiêu Nước/Gió/Băng, đòn đầu tiên mỗi vòng kéo lùi thêm 4% thanh lượt. | Tài nguyên: Điện Tích, tối đa 8. Đòn cơ bản chí mạng +1; đồng minh dùng kỹ năng tiêu Mana lần đầu mỗi vòng +1.','Pow tăng crit, tiêu Mana đều, thao túng thanh lượt và tạo nhiều hit.','1d1631bb','18.8.1'),
('umbrael','Sát thủ','Kết liễu','Bóng Tối Curse / Execute','Luật Hắc Ám','Luật Hắc Ám: Nguyền rủa do Umbrael đặt tạo thêm 1 Vết Bóng khi mục tiêu dùng kỹ năng; đủ 3 Vết Bóng thì lần sát thương kế tiếp của Umbrael lên mục tiêu bỏ qua 12% DEF. | Tài nguyên: Vết Bóng trên từng mục tiêu, tối đa 3; Hắc Tức trên Umbrael, tối đa 6 khi Nguyền gây hiệu ứng.','Đội Curse, execute, hút Mana, dồn mục tiêu thấp HP.','c7eab6e7','18.8.1'),
('calderion','Pháp sư','Bảo hộ','Dung Nham Phá Khiên / Nứt Giáp','Luật Nham Tâm','Luật Nham Tâm: lần đầu mỗi vòng Calderion gây sát thương lên Khiên, tạo 1 Nham Áp và phá thêm 8% Khiên hiện có. Kẻ đang Thiêu đốt bị giảm 6% hiệu quả Khiên mới. | Tài nguyên: Nham Áp tối đa 8; tạo khi đánh Khiên, khi Thiêu đốt tick hoặc khi Calderion nhận đòn trực tiếp, mỗi nguồn tối đa 1/vòng.','Carry phá Khiên, đội gây áp lực tuyến trước, debuff DEF.','fa30ed9f','18.8.1')
insert into public.pvp_pow_identity_v1881(pow_id,primary_role,secondary_role,archetype,passive_name,passive_summary,synergy,signature,source_version) values
('terrakor','Đỡ đòn','Kết liễu','Đất Thành Lũy / Phản Chấn','Luật Đại Địa','Luật Đại Địa: đồng minh đang được Terrakor bảo hộ không thể bị giảm quá 10% thanh lượt mỗi vòng. Terrakor nhận 1 Địa Tầng khi chặn hoặc nhận thay sát thương. | Tài nguyên: Địa Tầng tối đa 8; đòn trực tiếp +1, bảo hộ thành công +1; AOE chỉ +1 mỗi vòng.','Healer/Hiệp sĩ, Pow cần bảo hộ, đội hình phản chấn và đánh dài vòng.','ebe311cf','18.8.1'),
('pyrion','Đấu sĩ','Bảo hộ','Hỏa Thiêu Đốt','Luật Hỏa Tâm','Luật Hỏa Tâm: lần đầu mỗi vòng Pyrion gây Thiêu đốt hoặc đánh mục tiêu đang Thiêu đốt, nhận 1 Cuồng Nhiệt. Dưới 50% HP, lượng hồi từ bản thân tăng 15%. | Tài nguyên: Cuồng Nhiệt tối đa 8; kỹ năng gây sát thương +1 nếu chạm mục tiêu Thiêu đốt.','Pow gây Thiêu Đốt, giảm DEF/Khiên, hỗ trợ Mana hoặc tăng ATK/crit.','e1de3f51','18.8.1'),
('aquarion','Hiệp sĩ','Bảo hộ','Nước Sustain / Mana / Triều','Luật Hải Lưu','Luật Hải Lưu: lần đầu mỗi vòng một đồng minh nhận hồi Mana vượt trần hoặc hồi HP dư, 50% phần dư chuyển thành Khiên cho mục tiêu thấp HP nhất; có giới hạn theo AP/HP Aquarion. | Tài nguyên: Thủy Triều tối đa 8; bảo hộ thành công, hồi Mana đồng minh hoặc tạo Khiên từ phần dư +1, mỗi loại 1/vòng.','Healer/Mana support, Pow Băng/điều lượt, đội hình cần xoay skill liên tục.','1c2805a5','18.8.1'),
('ferronyx','Hiệp sĩ','Bảo hộ','Thép Khiên / Lời Thề','Luật Thiết Giáp','Luật Thiết Giáp: đòn chí mạng đầu tiên mỗi vòng lên Ferronyx hoặc mục tiêu được bảo hộ giảm 25% phần sát thương chí mạng cộng thêm và tạo 1 Tôi Luyện. | Tài nguyên: Tôi Luyện tối đa 8; chặn crit, Khiên vỡ có kiểm soát hoặc phản kích thành công +1.','Carry tuyến sau cần bảo hộ, healer/Khiên, đội phản kích.','4d2aabec','18.8.1'),
('glacior','Thuật sư','Khống chế','Băng Chill / Freeze','Luật Hàn Vực','Luật Hàn Vực: mọi giảm SPEED do Glacior đặt tạo 1 Hàn Khí, tối đa 5 mỗi mục tiêu. Ở 3 tầng, mục tiêu giảm thêm 5% thanh lượt khi hành động; ở 5 tầng mới đủ điều kiện Đóng Băng. | Tài nguyên: Hàn Khí trên mục tiêu + Sương Tâm trên Glacior tối đa 8 khi Hàn Khí kích hoạt.','Pow Nước/Chill, control, carry đánh mục tiêu bị chậm/Frozen.','7b3493bf','18.8.1'),
('vilexis','Thuật sư','Khống chế','Độc DoT / Anti-heal','Luật Độc Sinh','Luật Độc Sinh: Vilexis có ba loại Độc — Mòn (giảm DEF), Tê (giảm SPEED), Hoại (giảm hồi). Một mục tiêu có thể mang tối đa 2 loại; không loại nào là Nguyền rủa. | Tài nguyên: Mầm Độc tối đa 8; mỗi lần một loại Độc khác nhau tick +1, mỗi mục tiêu tối đa 1/vòng.','Đội DoT, anti-heal, đánh dài, execute mục tiêu bị bào mòn.','0f345d6c','18.8.1'),
('solarion','Trị liệu','Bảo hộ','Ánh Sáng Cleanse / Bảo Hộ','Luật Quang Minh','Luật Quang Minh: mỗi lần Solarion Thanh tẩy debuff đồng minh hoặc xóa buff địch, nhận 1 Quang Ấn, tối đa 8. Đây là hệ duy nhất có Thanh tẩy hoàn chỉnh. | Tài nguyên: Quang Ấn tối đa 8; Thanh tẩy/xóa buff +1, cứu đồng minh dưới 30% HP +1.','Đội cần Cleanse, bảo hộ và chống debuff; phù hợp carry dễ bị khóa.','506dbd9c','18.8.1'),
('verdantis','Trị liệu','Bảo hộ','Lá Hồi Phục / Sinh Trưởng','Luật Sinh Mệnh','Luật Sinh Mệnh: hồi máu trực tiếp gieo 1 Sinh Mầm lên mục tiêu, tối đa 3. Mỗi lượt Mầm nở hồi 2% HP mục tiêu; khi đạt 3 Mầm, lần hồi kế tiếp biến chúng thành Hoa Khiên. | Tài nguyên: Niên Luân tối đa 8; mỗi lần Mầm nở hoặc Hoa Khiên hấp thụ đòn +1, mỗi mục tiêu tối đa 1/vòng.','Tank/Hiệp sĩ, HoT/overheal, carry scaling theo vòng và đội đánh dài.','1b99dda5','18.8.1'),
('stormeon','Nhạc công','Khống chế','Bão Điều Lượt / Nhịp','Luật Phong Lôi','Luật Phong Lôi: trước lượt đầu tự dùng Khúc Dạo Bão Tố — toàn đội +8% SPEED và 5% thanh lượt. Mỗi 3 hành động đồng minh tạo 1 Phách Bão, tối đa 8. | Tài nguyên: Phách Bão tối đa 8; kỹ năng tăng/giảm thanh lượt lần đầu mỗi vòng +1 thêm.','Đội turn-control, nhiều hành động/Mana, carry hưởng lợi từ kéo nhịp.','2614179f','18.8.1'),
('zephyrion','Nhạc công','Điều lượt','Gió SPEED / Turn Tempo','Luật Thiên Phong','Luật Thiên Phong: trước combat chọn đồng minh SPEED cao nhất làm Người Dẫn Gió. Mỗi khi Người Dẫn Gió hành động, đồng minh thấp thanh lượt nhất nhận 4%, tối đa 1 lần/vòng. | Tài nguyên: Phong Nhịp tối đa 8; mỗi đồng minh khác nhau hành động lần đầu trong vòng +1, tối đa 4/vòng.','Carry nhanh, Nhạc công, Pow hưởng lợi từ SPEED/turn gauge.','855a6a45','18.8.1'),
('noxabyss','Pháp sư','Kết liễu','Bóng Tối Curse / Execute','Luật Tử Hồn','Luật Tử Hồn: lần đầu mỗi vòng một kẻ địch mang Nguyền xuống dưới 30% HP, Noxabyss nhận 1 Tử Hồn; một đơn vị thực sự ngã xuống cho +2 Tử Hồn. Tối đa 8 và không nhận từ Hồn Tướng/Cốt Long triệu hồi.','Đội Curse, execute, hút Mana, dồn mục tiêu thấp HP.','cb45c9a4','18.8.1'),
('frostmaw','Đỡ đòn','Kết liễu','Băng Chill / Freeze','Luật Bắc Minh','Luật Bắc Minh: nhận/chuyển sát thương trực tiếp hoặc giảm SPEED thành công tạo 1 Bắc Minh, tối đa 8; AOE chỉ tạo 1/vòng. Đòn đánh lên kẻ có Hàn Khí gây thêm sát thương theo DEF.','Pow Nước/Chill, control, carry đánh mục tiêu bị chậm/Frozen.','76d6f9ba','18.8.1'),
('magmorax','Đấu sĩ','Bảo hộ','Dung Nham Phá Khiên / Nứt Giáp','Luật Nham Hoàng','Luật Nham Hoàng: mỗi lần Magmorax mất ≥10% HP tối đa từ sát thương địch, phá hoàn toàn một Khiên, hoặc Thiêu đốt do Magmorax tick lần đầu trong vòng, nhận 1 Hỏa Chủng; tối đa 2/vòng và 8 tổng.','Carry phá Khiên, đội gây áp lực tuyến trước, debuff DEF.','6a819352','18.8.1'),
('venomarch','Thuật sư','Khống chế','Độc DoT / Anti-heal','Luật Cổ Độc Thiên Túc','Luật Cổ Độc Thiên Túc: lần đầu mỗi vòng khi một kẻ địch nhận Độc mới hoặc Độc của Venomarch gây tick, Venomarch nhận 1 Cổ Độc; nếu đối thủ được hồi HP khi đang có Độc, nhận thêm 1 Cổ Độc, tối đa 2 Cổ Độc/vòng và 8 tổng.','Đội DoT, anti-heal, đánh dài, execute mục tiêu bị bào mòn.','dad9c010','18.8.1'),
('luxarion','Trị liệu','Bảo hộ','Ánh Sáng Cleanse / Bảo Hộ','Luật Hoàng Quang','Luật Hoàng Quang: mỗi lần Luxarion Thanh tẩy debuff, chặn debuff bằng Khiên hoặc xóa buff địch thành công nhận 1 Nhật Ấn, tối đa 8; quyền Thanh tẩy hoàn chỉnh vẫn chỉ thuộc Ánh sáng.','Đội cần Cleanse, bảo hộ và chống debuff; phù hợp carry dễ bị khóa.','b99b5b78','18.8.1'),
('tempestrix','Nhạc công','Bảo hộ','Bão Điều Lượt / Nhịp','Luật Long Nhạc Phong Lôi','Luật Long Nhạc Phong Lôi: trước combat tự dùng Long Khúc Khai Thiên — toàn đội +10% SPEED và 6% thanh lượt. Sau mỗi 3 hành động chính của đồng minh nhận 1 Long Phách, tối đa 8; truy kích/phản kích không tính.','Đội turn-control, nhiều hành động/Mana, carry hưởng lợi từ kéo nhịp.','36ad8c3c','18.8.1'),
('starter_fire_flarion','Xạ thủ','Kết liễu','Hỏa Thiêu Đốt — Starter Core','Tàn Hỏa Bất Diệt','Tàn Hỏa Bất Diệt','Pow Hỏa/Burn, giảm DEF/Khiên, support crit/ATK/Mana; đồng đội càng đặt Burn đều, Tàn Hỏa/Hỏa Ấn càng chạy nhanh.','70855b4b','18.8.1'),
('starter_water_aquelion','Pháp sư','Kết liễu','Thủy–Băng — Starter Core','Thủy Ấn · Hàn Triều','Thủy Ấn · Hàn Triều','Pow Băng/Chill/Freeze, Nước/Mana support; Thủy Ấn chuẩn bị mục tiêu, đồng minh Băng tạo Hàn Triều.','218e0b65','18.8.1'),
('starter_leaf_sylvion','Trị liệu','Duy trì','Lá Hồi Phục / Tăng trưởng — Starter Core','Sinh Mạch · Sinh Hoa · Phồn Sinh','Sinh Mạch · Sinh Hoa · Phồn Sinh','Tank/Hiệp sĩ, Pow Lá HoT/overheal, carry đánh dài; heal càng nhiều thì Sinh Mạch/Phồn Sinh và damage đội càng tăng.','b97b9fbc','18.8.1')
